CREATE TYPE "TimetableVersionStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');

-- CreateEnum
CREATE TYPE "TimetableEntrySource" AS ENUM ('GENERATED', 'MANUAL');

-- CreateEnum
CREATE TYPE "TimetableRunStatus" AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED');

-- CreateEnum
CREATE TYPE "SolutionSource" AS ENUM ('CP_SAT', 'BASELINE');

-- CreateEnum
CREATE TYPE "SolverStatus" AS ENUM ('OPTIMAL', 'FEASIBLE', 'UNKNOWN');

-- CreateTable
CREATE TABLE "timetable_versions" (
    "id" TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "academicYearId" TEXT NOT NULL,
    "versionNumber" INTEGER NOT NULL,
    "status" "TimetableVersionStatus" NOT NULL DEFAULT 'DRAFT',
    "solutionSource" "SolutionSource" NOT NULL,
    "solverStatus" "SolverStatus" NOT NULL,
    "weightsVersion" TEXT NOT NULL,
    "inputHash" TEXT NOT NULL,
    "inputSnapshot" JSONB NOT NULL,
    "metrics" JSONB NOT NULL,
    "baselineMetrics" JSONB NOT NULL,
    "solverDiagnostics" JSONB,
    "createdById" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "timetable_versions_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "timetable_entries" (
    "id" TEXT NOT NULL,
