-- ===== Part 2: hand-written constraints =====

-- At most ONE queued or running generation per academic year, enforced by PostgreSQL itself (not by application code).
-- A SUCCEEDED or FAILED run does not count, so a new generation is allowed once the previous one has finished.
CREATE UNIQUE INDEX "timetable_generation_runs_one_active_per_year"
  ON "timetable_generation_runs" ("academicYearId")
  WHERE "status" IN ('QUEUED', 'RUNNING');

-- Versions are numbered from 1 within an academic year.
ALTER TABLE "timetable_versions"
  ADD CONSTRAINT "timetable_versions_version_number_check" CHECK ("versionNumber" >= 1);

-- Periods are numbered from 1.
ALTER TABLE "timetable_entries"
  ADD CONSTRAINT "timetable_entries_period_number_check" CHECK ("periodNumber" >= 1);
